        // i)
        if (deadDueTemperature && survivesTemperature(conditions.getTemperature()) && isSpring) {
            regrow();
        }
        // ii)
        else if (! deadDueTemperature) {
            // a)
            if (conditions.hasYearPassed()) {
                maxHealth++;
            }
            // b)
            reproduce(newPlants);
            grow();
        }
    }
}

